async function analyzeHealthText(text,host,question='',record=null){if(!confirm('AI analysis sends the extracted health text to the AI provider configured by this website. The provider may retain data under its policy. Continue only if you are authorized to share this record.'))return;host.textContent='Preparing a plain-language explanation…';try{const response=await fetch('/api/ai/analyze',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,question,language:selectedAiLanguage(),consent:true})}),data=await readJsonResponse(response,'AI analysis');if(!response.ok)throw Error(data.error||'AI analysis failed.');host.replaceChildren();const p=document.createElement('p');p.textContent=data.text;host.append(p);const notice=document.createElement('small');notice.className='disclaimer';notice.textContent=data.notice+' AI-generated voice.';host.append(notice);const button=document.createElement('button');button.type='button';button.className='btn btn-soft';button.textContent='🔊 Listen to AI explanation';button.onclick=()=>speakAiText(data.text,data.language||'en',button);host.append(button);if(record){const docs=read(STORAGE.docs,[]),index=docs.findIndex(d=>d.serverFileId===record.serverFileId);if(index>=0){docs[index].aiSummary=data.text;docs[index].aiLanguage=data.language||'en';await save(STORAGE.docs,docs)}}}catch(error){host.textContent=error.message||'AI analysis is unavailable.'}}
