function addFamily(){const name=document.getElementById('familyName').value.trim(),relation=document.getElementById('familyRelation').value.trim()||'Family';if(!name){toast('Add a name first.');return}const list=read(STORAGE.family,defaults.family);if(list.some(p=>p.name.trim().toLowerCase()===name.toLowerCase())){toast('A profile with this name already exists. Choose a different name to keep its records separate.');return}list.push({name,relation,records:0});save(STORAGE.family,list);document.getElementById('familyName').value='';document.getElementById('familyRelation').value='';closeModal('familyModal');renderFamily();toast('Family profile added on this device.')}
function renderFamily(){const host=document.getElementById('familyList');if(!host)return;const selected=familyName();host.innerHTML='';read(STORAGE.family,defaults.family).forEach((p,i)=>{const item=document.createElement('div');item.className='family-item'+(p.name===selected?' selected':'');item.innerHTML=`<div class="profile-photo">${i===0?'👤':'♧'}</div><b>${escapeHtml(p.name)}</b><div class="sub">${escapeHtml(p.relation)} · ${p.name===selected?read(STORAGE.docs,[]).length:(Number(p.records)||0)} records</div>${i>2?'<button type="button" class="text-btn">Remove</button>':''}`;item.onclick=e=>{if(e.target.tagName==='BUTTON')return;selectFamily(item,p.name)};if(i>2)item.querySelector('button').onclick=()=>{const all=read(STORAGE.family,defaults.family);all.splice(i,1);save(STORAGE.family,all);renderFamily()};host.append(item)})}
function resetChat(){const messages=document.getElementById("messages");if(!messages)return;messages.replaceChildren();const bubble=document.createElement("div");bubble.className="bubble";bubble.textContent="Ask about the records in the currently selected family profile. Responses use saved OCR text and may be inaccurate.";const button=document.createElement("button");button.className="text-btn";button.type="button";button.textContent="🔊 Speak reply";button.onclick=()=>speakText(bubble.textContent);bubble.append(document.createElement("br"),button);messages.append(bubble)}function selectFamily(el,name){save('hc_active_family',name);resetChat();renderFamily();renderProfile();renderDocuments();renderDashboard();renderReminders();renderTrends();renderDoctorPrep();updateCounts();toast(`Switched to ${name}. Each family profile has separate local records.`)}
