function checkInteractions(){const medicines=[document.getElementById('interactionMed1')?.value,document.getElementById('interactionMed2')?.value,...read(STORAGE.reminders,familyDefaults('reminders')).filter(m=>m.enabled).map(m=>m.name)].filter(Boolean).map(x=>x.toLowerCase());const result=document.getElementById('interactionResult');if(!result)return;const knownPairs=[['warfarin','omega-3','This demo list flags a possible warfarin and omega-3 interaction. Ask a pharmacist to review your complete medicine list.'],['levothyroxine','calcium','This demo list flags a possible levothyroxine and calcium interaction. Ask a pharmacist to review your complete medicine list.'],['levothyroxine','iron','This demo list flags a possible levothyroxine and iron interaction. Ask a pharmacist to review your complete medicine list.']];const match=knownPairs.find(([a,b])=>medicines.some(x=>x.includes(a))&&medicines.some(x=>x.includes(b)));result.innerHTML=match?`<b>${escapeHtml(match[2])}</b>`:'<b>No interaction was flagged by this limited demo list.</b> This is not a safety check and cannot rule out an interaction. Ask a pharmacist to review your complete medicine list.';result.hidden=false;const speak=document.createElement('button');speak.type='button';speak.className='text-btn';speak.textContent='🔊 Speak alert';speak.onclick=()=>speakText(result.innerText+' This demo list cannot rule out an interaction.');result.append(speak)}
function exportFHIR(){const docs=read(STORAGE.docs,[]),p=read(STORAGE.profile,{...defaults.profile,name:familyName()}),meds=read(STORAGE.reminders,[]),patientId='active-profile',patientRef='urn:uuid:'+crypto.randomUUID(),entry=[];const add=(resource,fullUrl)=>entry.push({fullUrl:fullUrl||'urn:uuid:'+crypto.randomUUID(),resource});const patient={resourceType:'Patient',id:patientId,active:true,name:[{text:p.name||familyName()}]};if(/^\d{4}-\d{2}-\d{2}$/.test(p.dob||''))patient.birthDate=p.dob;if(p.email)patient.telecom=[{system:'email',value:p.email}];add(patient,patientRef);docs.forEach((d,i)=>{const date=new Date(d.timestamp||Date.now()).toISOString();add({resourceType:'DocumentReference',id:`document-${i+1}`,status:'current',date,subject:{reference:patientRef},description:d.name,content:[{attachment:{contentType:'text/plain',title:`${d.name} (OCR text)`,data:btoa(Array.from(new TextEncoder().encode(d.text||'')).map(x=>String.fromCharCode(x)).join(''))}}]});(d.observations||[]).forEach((o,j)=>{const observation={resourceType:'Observation',id:`observation-${i+1}-${j+1}`,status:'preliminary',category:[{coding:[{system:'http://terminology.hl7.org/CodeSystem/observation-category',code:/blood pressure/i.test(o.name)?'vital-signs':'laboratory'}]}],code:{text:o.name},subject:{reference:patientRef},issued:date,note:[{text:'OCR from '+d.name+'; verify against the original report.'}],valueQuantity:{value:o.value,unit:o.unit,system:'http://unitsofmeasure.org',code:o.unit}};if(o.low!==null&&o.low!==undefined&&o.high!==null&&o.high!==undefined)observation.referenceRange=[{low:{value:o.low,unit:o.unit},high:{value:o.high,unit:o.unit}}];if(o.status==='below lab range')observation.interpretation=[{coding:[{system:'http://terminology.hl7.org/CodeSystem/v3-ObservationInterpretation',code:'L',display:'Low'}]}];if(o.status==='above lab range')observation.interpretation=[{coding:[{system:'http://terminology.hl7.org/CodeSystem/v3-ObservationInterpretation',code:'H',display:'High'}]}];add(observation)})});meds.forEach((m,i)=>add({resourceType:'MedicationStatement',id:`medication-${i+1}`,status:m.enabled?'active':'on-hold',medicationCodeableConcept:{text:m.name},subject:{reference:patientRef},dosage:[{text:m.schedule}]}));read(STORAGE.conditions,[]).forEach((c,i)=>add({resourceType:'Condition',id:`condition-${i+1}`,subject:{reference:patientRef},code:{text:c}}));read(STORAGE.allergies,[]).forEach((a,i)=>add({resourceType:'AllergyIntolerance',id:`allergy-${i+1}`,patient:{reference:patientRef},code:{text:a},verificationStatus:{coding:[{system:'http://terminology.hl7.org/CodeSystem/allergyintolerance-verification',code:'unconfirmed'}]}}));const data={resourceType:'Bundle',type:'collection',timestamp:new Date().toISOString(),entry};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/fhir+json'}));a.download='healthcopilot-fhir-r4.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('FHIR R4 bundle for the selected profile downloaded. Confirm OCR values before sharing.')}
async function clearDemo(){if(!confirm('Delete all AYUSH+ data for this account, including encrypted originals on the server? This cannot be undone.'))return;if(currentAccount){try{await syncQueue;const response=await fetch('/api/data',{method:'DELETE',credentials:'same-origin'});if(!response.ok)throw Error('Server could not delete account data.');remoteAccountData={}}catch(error){toast(error.message);return}}const suffix='::'+accountScope();for(let i=localStorage.length-1;i>=0;i--){const key=localStorage.key(i);if(key?.startsWith('hc_')&&(key.endsWith(suffix)||key.includes(suffix+'::')))localStorage.removeItem(key)}location.reload()}
