let ocrWorkerPromise=null,ocrWorkerLang='';
function setupUpload(){const zone=document.getElementById('dropZone'),input=document.getElementById('fileInput');if(!zone||!input)return;const lang=document.createElement('label');lang.className='sub';lang.style.cssText='display:block;margin-top:14px';lang.textContent='OCR mode ';const select=document.createElement('select');select.id='ocrLanguage';select.className='field';select.innerHTML='<option value="eng">Printed English</option><option value="eng+hin">Printed English + Hindi</option><option value="tam">Printed Tamil</option><option value="tel">Printed Telugu</option><option value="kan">Printed Kannada</option><option value="mal">Printed Malayalam</option><option value="eng-hand">Handwriting (English · best effort)</option><option value="eng+hin-hand">Handwriting (English + Hindi · best effort)</option>';lang.append(select);const hint=document.createElement('small');hint.className='disclaimer';hint.textContent='Handwriting mode changes OCR page segmentation; handwriting can still be misread. Always verify values on the original.';lang.append(document.createElement('br'),hint);zone.after(lang);['dragenter','dragover'].forEach(ev=>zone.addEventListener(ev,e=>{e.preventDefault();zone.style.background='#eaf6f1'}));['dragleave','drop'].forEach(ev=>zone.addEventListener(ev,e=>{e.preventDefault();zone.style.background=''}));zone.addEventListener('drop',e=>handleFiles(e.dataTransfer.files));input.addEventListener('change',()=>{handleFiles(input.files);input.value=''});if(window.pdfjsLib)pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';}
function getOcrWorker(status=window.ocrActiveStatus){
 if(!window.Tesseract)throw Error('OCR library could not load. Check your internet connection and reload.');
 const mode=document.getElementById('ocrLanguage')?.value||'eng',hand=mode.endsWith('-hand'),lang=mode.replace('-hand','');
 if(!ocrWorkerPromise||ocrWorkerLang!==mode){
  const previous=ocrWorkerPromise;ocrWorkerLang=mode;
  const pending=(async()=>{
   if(previous){try{(await previous).terminate()}catch{}}
   const worker=await Tesseract.createWorker(lang,1,{logger:m=>{
    if(!status)return;
    if(m.status==='recognizing text')status.textContent='Recognizing text… '+Math.round((m.progress||0)*100)+'%';
    else if(m.status&&m.status!=='loading tesseract core')status.textContent='Preparing OCR: '+m.status.replace(/_/g,' ')+'…';
    else if(m.status==='loading tesseract core')status.textContent='Loading OCR engine…';
   }});
   if(hand)await worker.setParameters({tessedit_pageseg_mode:'11'});
   return worker;
  })();
  ocrWorkerPromise=pending;
  pending.catch(()=>{if(ocrWorkerPromise===pending){ocrWorkerPromise=null;ocrWorkerLang=''}});
 }
 return ocrWorkerPromise;
}
async function recognizeFile(file,status){
 const ext=file.name.split('.').pop().toLowerCase();
 if(['txt','csv','json','md','log','html','htm','rtf'].includes(ext)){
  let text=await file.text();
  if(['html','htm'].includes(ext)){const doc=new DOMParser().parseFromString(text,'text/html');doc.querySelectorAll('script,style,template,noscript').forEach(x=>x.remove());text=doc.body?.innerText||doc.documentElement.textContent||''}
  if(ext==='rtf')text=text.replace(/\\'[0-9a-f]{2}/gi,' ').replace(/\\[a-z]+-?\d* ?/gi,' ').replace(/[{}]/g,' ').replace(/\\\\/g,'\\');
  if(ext==='json'){try{text=JSON.stringify(JSON.parse(text),null,2)}catch{throw Error('This JSON file is malformed.')}}
  return text.slice(0,200000).trim()
 }
 if(file.type==='application/pdf'||ext==='pdf'){
  if(!window.pdfjsLib)throw Error('PDF reader could not load. Check your internet connection and reload.');
  const pdf=await pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise,limit=Math.min(pdf.numPages,20),pages=[];
  for(let n=1;n<=limit;n++){
   status.textContent=`Checking PDF text · page ${n} of ${limit}`;
   const page=await pdf.getPage(n);
   let pageText='';
   try{
   const content=await page.getTextContent(),nativeText=content.items.map(item=>typeof item.str==='string'?item.str:'').join(' ').trim();
   pageText=nativeText;
   if(nativeText.replace(/\s/g,'').length<140){
   status.textContent=`Scanning page ${n} of ${limit} with OCR…`;
    const initialViewport=page.getViewport({scale:2}),scale=Math.min(1,2400/Math.max(initialViewport.width,initialViewport.height)),viewport=page.getViewport({scale:2*scale}),canvas=document.createElement('canvas');
    canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);
    try{await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;pageText=(await(await getOcrWorker(status)).recognize(canvas)).data.text.trim()}
    finally{canvas.width=canvas.height=1}
   }
   }finally{page.cleanup()}
   if(pageText)pages.push(`--- Page ${n} ---\n${pageText}`);
  }
  if(pdf.numPages>limit)pages.push(`[Only the first ${limit} of ${pdf.numPages} pages were processed.]`);
  return pages.join('\n\n').slice(0,200000).trim()
 }
 if(/^image\/(png|jpeg)$/.test(file.type)||/\.(png|jpe?g)$/i.test(file.name)){
  status.textContent='Preparing OCR engine…';
  const worker=await getOcrWorker(status);
  if(typeof createImageBitmap==='function'){
   const bitmap=await createImageBitmap(file),scale=Math.min(1,2400/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');
   canvas.width=Math.max(1,Math.ceil(bitmap.width*scale));canvas.height=Math.max(1,Math.ceil(bitmap.height*scale));
   try{canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);return(await worker.recognize(canvas)).data.text.trim()}
   finally{bitmap.close();canvas.width=canvas.height=1}
  }
  return(await worker.recognize(file)).data.text.trim();
 }
 throw Error('Unsupported format. Use PDF, PNG/JPG, TXT, CSV, JSON, Markdown, HTML or RTF.')
}
